args <- commandArgs(TRUE)
stopifnot(length(args)==3)
.libPaths(c(normalizePath(args[1]),.Library),include.site=FALSE)
library(dplyr); library(tidyr); library(ggplot2)
input <- normalizePath(args[2]); out <- args[3]
if(dir.exists(out)) stop('Output exists')
dir.create(out,recursive=TRUE)
write_table <- function(x,n) write.csv(x,file.path(out,n),row.names=FALSE,na='NA')
save_plot <- function(p,n,w=11,h=7) ggsave(file.path(out,n),p,width=w,height=h,dpi=180,bg='white',limitsize=TRUE)
theme_set(theme_minimal(base_size=11)+theme(plot.title=element_text(face='bold'),plot.caption=element_text(hjust=0,size=9),panel.grid.minor=element_blank()))
x <- read.csv(file.path(input,'zperturb_beta_bin_results_broadtype_clean.csv'),check.names=FALSE)
x$source_row <- seq_len(nrow(x))
pig <- x %>% filter(grepl('phore|pigmented',cell_group,ignore.case=TRUE))
stopifnot(all(is.finite(pig$estimate)),!anyNA(pig$gene1),!anyNA(pig$timepoint))
write_table(pig,'estimate-source-rows.csv')
temporal <- pig %>% group_by(gene1,timepoint) %>% summarise(mean_model_estimate=mean(estimate),source_rows=n(),.groups='drop')
# Preserve unobserved combinations as NA, never zero.
grid <- temporal %>% complete(gene1,timepoint) %>% arrange(gene1,timepoint)
grid$observed <- !is.na(grid$source_rows)
write_table(grid,'estimates-by-time.csv')
ranking <- pig %>% group_by(gene1) %>% summarise(mean_model_estimate=mean(estimate),source_rows=n(),observed_times=n_distinct(timepoint),.groups='drop') %>% arrange(desc(mean_model_estimate),gene1)
ranking$rank <- seq_len(nrow(ranking));ranking$tied_mean <- duplicated(ranking$mean_model_estimate)|duplicated(ranking$mean_model_estimate,fromLast=TRUE)
write_table(ranking,'estimates-ranking-all.csv');write_table(head(ranking,10),'estimates-ranking-top10.csv')
p <- ggplot(grid,aes(timepoint,mean_model_estimate,group=gene1))+geom_line(na.rm=TRUE,color='#237c89')+geom_point(na.rm=TRUE,color='#237c89')+facet_wrap(~gene1,ncol=4)+scale_x_continuous(breaks=c(18,24,36,48,72))+labs(title='Estimativas do modelo por gene e tempo',subtitle='Média das linhas dos grupos pigmentares; escala vertical comum',x='Tempo (h)',y='Média de estimate',caption='Fonte: tabela beta-binomial de Saunders e colaboradores. Não é expressão génica medida.\nCombinações sem observações ficam ausentes (NA); não foram imputadas como zero.')
save_plot(p,'estimates-by-time.png',12,11)
p <- ggplot(head(ranking,10),aes(reorder(gene1,mean_model_estimate),mean_model_estimate))+geom_col(fill='#237c89')+coord_flip()+labs(title='Dez maiores médias de estimate',subtitle='Média de todas as linhas pigmentares por gene, abrangendo os tempos disponíveis',x='Gene',y='Média de estimate',caption='Não é um ranking de expressão génica nem um novo teste de expressão diferencial.\nCada linha contribui igualmente; não se usa a média simples das médias por tempo.')
save_plot(p,'estimates-ranking.png')
v <- read.csv(file.path(input,'ref_broad_celltype_disps.csv'),check.names=FALSE);v$source_row <- seq_len(nrow(v))
all <- v %>% filter(cells_per_embryo>3)
sel <- all %>% filter(timepoint %in% c(20,22,24,42)) %>% mutate(p_below_005=cv_z_stat_p_val<0.05,cv_minus_stderr=cells_per_embryo_cv-cells_per_embryo_cv.stderr,cv_plus_stderr=cells_per_embryo_cv+cells_per_embryo_cv.stderr)
write_table(all,'abundance-all-filtered.csv');write_table(sel,'abundance-selected-times.csv')
# Audit positive finite values required for logarithmic rendering.
audit <- sel %>% transmute(source_row,timepoint,cell_group,x_valid=is.finite(cells_per_embryo)&cells_per_embryo>0,cv_valid=is.finite(cells_per_embryo_cv)&cells_per_embryo_cv>0,fit_valid=is.finite(model_fit)&model_fit>0,fit_bounds_valid=is.finite(model_fit_lower)&model_fit_lower>0&is.finite(model_fit_upper)&model_fit_upper>0,errorbar_valid=is.finite(cv_minus_stderr)&cv_minus_stderr>0&is.finite(cv_plus_stderr)&cv_plus_stderr>0)
write_table(audit,'log-scale-audit.csv')
stopifnot(all(audit$x_valid),all(audit$cv_valid),all(audit$fit_valid),all(audit$fit_bounds_valid))
p <- ggplot(sel,aes(cells_per_embryo,cells_per_embryo_cv))+geom_ribbon(aes(ymin=model_fit_lower,ymax=model_fit_upper),alpha=.15)+geom_line(aes(y=model_fit),color='#333333')+geom_point(aes(color=p_below_005),size=1.5)+geom_linerange(data=sel %>% filter(p_below_005,cv_minus_stderr>0),aes(ymin=cv_minus_stderr,ymax=cv_plus_stderr),linewidth=.3)+facet_wrap(~timepoint,scales='free_x',nrow=1)+scale_x_log10()+scale_y_log10()+scale_color_manual(values=c('FALSE'='#437b9c','TRUE'='#c85b40'),labels=c('FALSE'='p ≥ 0,05','TRUE'='p < 0,05'),na.value='grey60')+labs(title='Variabilidade da abundância celular por tempo',subtitle='Todas as classes presentes na tabela filtrada; células por embrião > 3',x='Células por embrião (escala log)',y='Coeficiente de variação (escala log)',color='p fornecido',caption='Ajuste e faixa: model_fit e limites fornecidos na tabela; nenhum modelo foi recalculado.\nBarras: CV ± erro-padrão para p < 0,05. Limiar nominal; não implica correção por testes múltiplos.')
save_plot(p,'abundance-by-time.png',14,6)
summary <- all %>% group_by(cell_group) %>% summarise(rows=n(),median_cv_test_stat=median(cv_test_stat),.groups='drop') %>% arrange(median_cv_test_stat)
write_table(summary,'abundance-group-summary.csv')
p <- ggplot(all,aes(reorder(cell_group,cv_test_stat,FUN=median),cv_test_stat))+geom_boxplot(fill='#9ac6ce',outlier.size=.7)+coord_flip()+labs(title='Estatística de variabilidade por classe celular',subtitle='Distribuição das linhas/tempos da tabela com células por embrião > 3',x='Classe celular',y='cv_test_stat',caption='Estatística fornecida pelo estudo; não é variância da expressão génica.\nClasses ordenadas pela mediana; não restrito às células pigmentares.')+theme(axis.text.y=element_text(size=8))
save_plot(p,'abundance-by-group.png',12,max(8,nrow(summary)*.19))
write_table(data.frame(metric=c('pigment_source_rows','observed_gene_time','missing_gene_time','ranked_genes','abundance_rows','selected_time_rows','nonpositive_errorbar_selected'),value=c(nrow(pig),nrow(temporal),sum(!grid$observed),nrow(ranking),nrow(all),nrow(sel),sum(sel$p_below_005 & !audit$errorbar_valid,na.rm=TRUE))),'checks.csv')
capture.output(sessionInfo(),file=file.path(out,'session-info.txt'))
